// The song's colours: how much each of the twelve tones sounds (notes per pitch class).
function _pcWeights(chords){ const w=new Array(12).fill(0); for(const c of (chords||[])){ const ns=(c&&(c.n||c.notes))||[]; for(const x of ns){ const m=(x&&x.m!==undefined)?x.m:x; w[((Math.round(+m||0)%12)+12)%12]+=1; } } return w; }
const _FIFTHS=[0,7,2,9,4,11,6,1,8,3,10,5];
// a rounded rectangle as a path (all four corners) — the painting in a Web / Story export, as it is in the app
function _rrPath(cx,x,y,w,h,r){ r=Math.max(0,Math.min(r,w/2,h/2)); cx.beginPath(); if(!r){ cx.rect(x,y,w,h); return; } cx.moveTo(x+r,y); cx.arcTo(x+w,y,x+w,y+h,r); cx.arcTo(x+w,y+h,x,y+h,r); cx.arcTo(x,y+h,x,y,r); cx.arcTo(x,y,x+w,y,r); cx.closePath(); }
function _rrect(cx,x,y,w,h,r){ cx.beginPath(); cx.moveTo(x+r,y); cx.lineTo(x+w-r,y); cx.quadraticCurveTo(x+w,y,x+w,y+r); cx.lineTo(x+w,y+h); cx.lineTo(x,y+h); cx.lineTo(x,y+r); cx.quadraticCurveTo(x,y,x+r,y); cx.closePath(); }
// Twelve bars in fifths, in the palette's colours (gc), each as tall as its tone sounds in the song, the tone's name under it.
function _drawPcStrip(cx, x, y, w, h, wts, gc, names, o){
  o=o||{}; const gap=(o.gap!=null) ? o.gap : w*0.014; const bw=(w-11*gap)/12; const fs=o.font||Math.max(8,Math.round(bw*0.36)); const lh=Math.round(fs*1.6);
  const bh=h-lh; const mx=Math.max(1,...wts); const minH=Math.max(2,bh*0.06);
  cx.save(); cx.textAlign='center'; cx.textBaseline='alphabetic'; cx.font=`500 ${fs}px "Outfit", Arial, sans-serif`;
  _FIFTHS.forEach((pc,i)=>{ let c=[160,160,160]; try{ c=gc(72+pc,110); }catch(_){}
    const bx=x+i*(bw+gap); const hh=wts[pc]>0 ? Math.max(minH, bh*wts[pc]/mx) : minH*0.5;
    cx.fillStyle=`rgb(${c[0]|0},${c[1]|0},${c[2]|0})`; _rrect(cx,bx,y+bh-hh,bw,hh,Math.min(bw*0.14,hh/2)); cx.fill();
    cx.fillStyle=o.labelColor||'rgba(230,222,196,.72)'; cx.fillText((names&&names[pc])||'', bx+bw/2, y+bh+lh*0.85); });
  cx.restore();
}
// a palette's name in a caption, capitalised (Harmónia); the two-letter marks (b/w, č/b) in capitals
const _PAL_KEYS=/^(harmony|spectral|phi|kontra|custom|bw)$/;
function _palCap(s){ s=String(s||''); return /^\S{1,2}[\/&]\S{1,2}$/.test(s) ? s.toUpperCase() : s.charAt(0).toUpperCase()+s.slice(1); }
// one line that fits: the font shrinks to `min`, then the text is cut with an ellipsis
function _fitText(cx, txt, maxW, size, min, fontFn){ let s=size; cx.font=fontFn(s); while(s>min && cx.measureText(txt).width>maxW){ s-=1; cx.font=fontFn(s); } if(cx.measureText(txt).width<=maxW) return txt; let t=txt; while(t.length>1 && cx.measureText(t+'…').width>maxW) t=t.slice(0,-1); return t+'…'; }
// Web / Print with a caption: the painting on the dark ground; under it the title, the painters and the song's colours.
// Print is an A1 sheet (594 × 841) holding as many pixels as the painting had, so a phone's canvas limit still holds.
// the source picture in the export band: fit inside bw×bh, a thin gold hairline, a small round corner
function _srcBox(im, bw, bh){ const iw=im.naturalWidth||im.width, ih=im.naturalHeight||im.height; const k=Math.min(bw/iw, bh/ih); return { w:Math.round(iw*k), h:Math.round(ih*k) }; }
function _drawSrc(cx, im, x, y, w, h, W){ const r=Math.round(W*0.006);
  cx.save(); cx.beginPath(); if(cx.roundRect) cx.roundRect(x,y,w,h,r); else cx.rect(x,y,w,h); cx.clip(); cx.imageSmoothingQuality='high'; cx.drawImage(im,x,y,w,h); cx.restore();
  cx.save(); cx.strokeStyle='rgba(201,168,76,.45)'; cx.lineWidth=Math.max(1,W*0.0012); cx.beginPath(); if(cx.roundRect) cx.roundRect(x,y,w,h,r); else cx.rect(x,y,w,h); cx.stroke(); cx.restore(); }
function _frameExport(hi, kind, o){
  const GOLD='rgba(201,168,76,.85)', CREAM='#f4e7c6', SOFT='rgba(230,222,196,.72)';
  const serifI=(s)=>`italic 600 ${s}px "Cormorant Garamond", Georgia, serif`, serifI5=(s)=>`italic 500 ${s}px "Cormorant Garamond", Georgia, serif`, sans=(s)=>`500 ${s}px "Outfit", Arial, sans-serif`;
  const cv=document.createElement('canvas'); let cx;
  // Web and Print share ONE layout (painting in a dark mat, the caption centred under it); Print keeps the A-sheet ratio, Web hugs the painting
  {
    const isP=(kind==='print');
    const area=hi.width*hi.height; const Wf=isP ? Math.round(Math.sqrt(area*594/841)) : hi.width;
    const m=Math.round(Wf*(isP ? 0.094 : 0.07));
    const cb0=Math.round(Wf*(o.bare ? 0.24 : o.src ? 0.46 : 0.36));
    const Hf=isP ? Math.round(Wf*841/594) : (m + Math.round(hi.height*(Wf-2*m)/hi.width) + cb0);
    cv.width=Wf; cv.height=Hf; cx=cv.getContext('2d');
    cx.fillStyle='#0b0b10'; cx.fillRect(0,0,Wf,Hf);
    const cb=isP ? Math.round(Hf*((o.src && !o.bare) ? 0.30 : 0.25)) : cb0;
    const bw=Wf-2*m, bh=Hf-m-cb; const k=Math.min(bw/hi.width, bh/hi.height); const pw=Math.round(hi.width*k), ph=Math.round(hi.height*k);
    const px=Math.round((Wf-pw)/2), py=m+Math.round((bh-ph)/2);
    const rr = isP ? 0 : Math.round(Math.min(pw,ph)*0.045);   // Web: the painting's corners round, as in the app — a print keeps them sharp
    cx.save(); _rrPath(cx,px,py,pw,ph,rr); cx.clip(); cx.imageSmoothingQuality='high'; cx.drawImage(hi,px,py,pw,ph); cx.restore();
    cx.strokeStyle='rgba(201,168,76,.5)'; cx.lineWidth=Math.max(2,Wf*0.0017); _rrPath(cx,px,py,pw,ph,rr); cx.stroke();
    let bw2=bw;
    if(o.bare){ if(o.src){ const r=_srcBox(o.src, Math.round(Wf*0.22), Math.round(cb*0.6)); _drawSrc(cx, o.src, Math.round((Wf-r.w)/2), Hf-cb+Math.round((cb-r.h)/2), r.w, r.h, Wf); } return cv; }
    let y=Hf-cb+Math.round(Wf*0.07);
    // the source: a small badge centred under the painting, the caption below it
    if(o.src){ const r=_srcBox(o.src, Math.round(Wf*0.09), Math.round(Wf*0.09)); _drawSrc(cx, o.src, Math.round((Wf-r.w)/2), Hf-cb+Math.round(Wf*0.03), r.w, r.h, Wf); y+=r.h+Math.round(Wf*0.01); }
    cx.textAlign='center';
    if(o.title){ cx.fillStyle=CREAM; const t=_fitText(cx,o.title,bw2,Math.round(Wf*0.044),Math.round(Wf*0.02),serifI); cx.fillText(t,Wf/2,y); y+=Math.round(Wf*0.036); }
    if(o.composer){ cx.fillStyle=SOFT; const t=_fitText(cx,o.composer,bw2,Math.round(Wf*0.02),Math.round(Wf*0.012),sans); cx.fillText(t,Wf/2,y); y+=Math.round(Wf*0.034); }
    const _il=o.insp ? (o.palN ? o.insp+'  |  '+o.palN : o.insp) : (o.pal||'');
    if(_il){ cx.fillStyle=GOLD; const t=_fitText(cx,_il,bw2,Math.round(Wf*0.025),Math.round(Wf*0.014),serifI5); cx.fillText(t,Wf/2,y); y+=Math.round(Wf*0.03); }
    const sw=Math.min(Math.round(Wf*0.54), bw2); _drawPcStrip(cx, Math.round((Wf-sw)/2), y, sw, Math.round(Wf*0.092), o.wts, o.gc, o.names, {font:Math.round(Wf*0.015)});
    cx.textAlign='center'; cx.fillStyle='rgba(201,168,76,.7)'; cx.font=sans(Math.round(Wf*0.017)); cx.fillText('Paintiano · '+(o.tag||'music → φ painting'), Wf/2, Hf-Math.round(m*0.5));   // a picture's export: φ painting → music
    return cv;
  }
}

