                setActive(p=>{const s=new Set(p); s.add(mn.m); return s;});
                pushTimer(()=>setActive(p=>{const s=new Set(p); s.delete(mn.m); return s;}), Math.min(900, Math.round(durMs/playbackSpeedRef.current)));
