              try{ stashMode('music'); }catch(_){}
              try{ stopAll(); }catch(_){}
              try{ wipeCanvasNow(); }catch(_){}
              setShowMoodMenu(false);setShowMorphMenu(false);setShowComposeRecent(false);setShowMicRecent(false);setPickMode(null);
              const ok = restoreMode('image');
