        const toggleArt = (k)=> setSetupArtists(prev => prev.includes(k) ? prev.filter(x=>x!==k) : [...prev, k]);
        const okMin = setupPalettes.length>=1 && setupArtists.length>=1 && setupTones.length>=1;
        const _px = (n)=> ((n/16)*effScale)+'rem';
